"page.machines-controle.item6": {"fr": "<strong>Contrôle par vision industrielle et caméra</strong>", "en": "<strong>Inspection by industrial vision and camera</strong>", "it": "<strong>Controllo tramite visione industriale e telecamera</strong>", "de": "<strong>Prüfung mit industrieller Bildverarbeitung und Kamera</strong>", "es": "<strong>Control por visión industrial y cámara</strong>", "pt": "<strong>Controlo por visão industrial e câmara</strong>", "ro": "<strong>Control prin viziune industrială și cameră</strong>"},
